import os
import sys
from rich.console import Console

def test_broken_pipe():
    # Create a pipe
    r, w = os.pipe()

    # Close the read end immediately to simulate a broken pipe
    os.close(r)

    console = Console(file=os.fdopen(w, 'w'))

    try:
        console.print("This should trigger a BrokenPipeError")
        print("Failed: BrokenPipeError was not raised or handled")
    except SystemExit:
        print("Success: SystemExit caught (BrokenPipeError handled)")
    except BrokenPipeError:
        print("Failed: BrokenPipeError was not handled")
    except Exception as e:
        print(f"Failed: Unexpected exception {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_broken_pipe()

